# Let me visualize the structure better by looking at rectangles

# Look for hollow rectangles in top section - where would the "holes" be?
# A hollow rectangle is when a color forms a border and 0s inside

import math

def find_hollow_rectangles(grid, color, separator_row):
    rows, cols = len(grid), len(grid[0])
    rectangles = []

    # For each point, check if it could be top-left of a hollow rectangle
    for r1 in range(separator_row):
        for c1 in range(cols):
            if grid[r1][c1] == color:
                for r2 in range(r1+1, separator_row):
                    for c2 in range(c1+1, cols):
                        if grid[r2][c2] == color:
                            # Check if this forms a hollow rectangle
                            is_hollow = True
                            hole_area = 0

                            # Check all edges
                            for r in range(r1, r2+1):
                                if grid[r][c1] != color or grid[r][c2] != color:
                                    is_hollow = False
                                    break
                            if is_hollow:
                                for c in range(c1+1, c2):
                                    if grid[r1][c] != color or grid[r2][c] != color:
                                        is_hollow = False
                                        break
                            if is_hollow:
                                # Count interior (0s inside the rectangle)
                                for r in range(r1+1, r2):
                                    for c in range(c1+1, c2):
                                        if grid[r][c] == 0:
                                            hole_area += 1

                                # Check if interior is all 0s
                                interior_empty = True
                                for r in range(r1+1, r2):
                                    for c in range(c1+1, c2):
                                        if grid[r][c] != 0:
                                            interior_empty = False
                                            break

                            if is_hollow and interior_empty:
                                height = r2 - r1
                                width = c2 - c1
                                interior_area = (height-2) * (width-2)  # excludes border
                                rectangles.append({'r1': r1, 'c1': c1, 'r2': r2, 'c2': c2, 
                                                   'height': height, 'width': width, 
                                                   'interior_area': interior_area, 
                                                   'is_even': interior_area % 2 == 0})
    return rectangles

